-- =============================================================================
-- SAIL Tour Management System — Core transactional tables
-- Run as sail_tour_app after 010_masters.sql
-- =============================================================================

-- ---------------------------------------------------------------------------
-- TOUR_REQUEST
-- SSoT §20: header entity. Optimistic locking via version_no (SSoT §17 VAL-16).
-- request_number / control_number formats are TBD (SSoT §25) — generated by
-- the Node.js service using a placeholder format documented in
-- apps/api/src/domain/request-number.ts, isolated behind one function so the
-- real format can be swapped in without touching callers.
-- ---------------------------------------------------------------------------
CREATE SEQUENCE tour_request_seq START WITH 1000 INCREMENT BY 1 NOCACHE;

CREATE TABLE tour_request (
  request_id                 NUMBER          NOT NULL,
  request_number              VARCHAR2(40)   NOT NULL,
  control_number               VARCHAR2(40),
  -- Employee identity — sourced from Fusion HCM at submit time, never trusted
  -- from the client (SSoT VAL-01). person_number is the durable HCM anchor.
  person_number                VARCHAR2(30)   NOT NULL,
  staff_no                     VARCHAR2(30)   NOT NULL,
  scale_code                   VARCHAR2(30),
  employee_name                VARCHAR2(240)  NOT NULL,
  department                   VARCHAR2(240),
  grade_code                   VARCHAR2(30)   NOT NULL,   -- FK-by-value into ta_rule_master.grade_code
  headquarter                  VARCHAR2(120)  NOT NULL,
  -- Tour details (SSoT S7)
  commencement_date            DATE           NOT NULL,
  travel_start_date            DATE           NOT NULL,
  travel_end_date              DATE           NOT NULL,
  tour_type                    VARCHAR2(80)   NOT NULL,
  dest_code                    VARCHAR2(20)   NOT NULL,
  purpose                      VARCHAR2(500 CHAR) NOT NULL,  -- VAL-07: <=500 chars
  -- Travel permissions (SSoT S8)
  road_travel_permission       VARCHAR2(20)   DEFAULT 'No' NOT NULL,
  vehicle_number                VARCHAR2(30),
  air_travel_permission         VARCHAR2(5)   DEFAULT 'No' NOT NULL,
  -- Rail Travel Permission — explicit field added at the client's direction
  -- (current-system screenshot, Sep 2026), mirroring air_travel_permission's
  -- No/Yes shape; rail grade entitlement itself still comes from
  -- ta_rule_master.rail_entitlement regardless of this flag.
  rail_travel_permission         VARCHAR2(5)   DEFAULT 'No' NOT NULL,
  -- Exception/approval flags evaluated by the TA rule engine (SSoT S15.3, VAL-11/12/13)
  non_shortest_route_flag       CHAR(1)       DEFAULT 'N' NOT NULL,
  higher_class_approval_flag    CHAR(1)       DEFAULT 'N' NOT NULL,
  own_vehicle_approval_flag     CHAR(1)       DEFAULT 'N' NOT NULL,
  competent_authority_approver  VARCHAR2(30),              -- person_number of approving Competent Authority, when applicable
  pnr_ticket_number              VARCHAR2(60),               -- VAL-14
  -- Advance
  advance_required               CHAR(1)      DEFAULT 'N' NOT NULL,
  -- Workflow
  status                          VARCHAR2(30) DEFAULT 'DRAFT' NOT NULL,
  financial_year                  VARCHAR2(10),
  version_no                      NUMBER(10)   DEFAULT 1 NOT NULL,  -- optimistic locking, VAL-16
  created_by                      VARCHAR2(30) NOT NULL,
  created_at                      TIMESTAMP    DEFAULT SYSTIMESTAMP NOT NULL,
  updated_at                      TIMESTAMP,
  submitted_at                    TIMESTAMP,
  CONSTRAINT pk_tour_request PRIMARY KEY (request_id),
  CONSTRAINT uq_tour_request_number UNIQUE (request_number),
  CONSTRAINT fk_tour_request_dest FOREIGN KEY (dest_code) REFERENCES destination_master (dest_code),
  CONSTRAINT chk_tour_request_dates CHECK (travel_end_date >= travel_start_date),  -- VAL-02
  CONSTRAINT chk_tour_commencement_date CHECK (travel_start_date >= commencement_date),
  CONSTRAINT chk_tour_road_perm CHECK (road_travel_permission IN
    ('No', 'Own Vehicle', 'Hired Vehicle', 'Vehicle Retention')),
  CONSTRAINT chk_tour_air_perm CHECK (air_travel_permission IN ('No', 'Yes')),
  CONSTRAINT chk_tour_rail_perm CHECK (rail_travel_permission IN ('No', 'Yes')),
  CONSTRAINT chk_tour_flags CHECK (
    non_shortest_route_flag IN ('Y','N') AND
    higher_class_approval_flag IN ('Y','N') AND
    own_vehicle_approval_flag IN ('Y','N') AND
    advance_required IN ('Y','N')
  ),
  CONSTRAINT chk_tour_status CHECK (status IN (
    'DRAFT', 'PENDING_FORWARDING', 'FORWARDED', 'PENDING_RECOMMENDATION',
    'RECOMMENDED', 'PENDING_APPROVAL', 'APPROVED', 'REJECTED', 'CANCELLED'
  ))
);

CREATE INDEX idx_tour_request_person ON tour_request (person_number);
CREATE INDEX idx_tour_request_status ON tour_request (status);
CREATE INDEX idx_tour_request_created ON tour_request (created_at DESC);
CREATE INDEX idx_tour_request_dest ON tour_request (dest_code);

COMMENT ON COLUMN tour_request.version_no IS
  'Optimistic locking column. Every UPDATE must check and increment this (SSoT VAL-16).';

-- Trigger: maintain updated_at + version_no on every update.
CREATE OR REPLACE TRIGGER trg_tour_request_biu
BEFORE UPDATE ON tour_request
FOR EACH ROW
BEGIN
  :NEW.updated_at := SYSTIMESTAMP;
  :NEW.version_no := :OLD.version_no + 1;
END;
/

-- ---------------------------------------------------------------------------
-- TOUR_ADVANCE
-- SSoT §11: per-category advance line items, one row per category on a request.
-- A role may edit only its permitted stage column — enforced in the service
-- layer (apps/api/src/modules/advances), not just here.
-- ---------------------------------------------------------------------------
CREATE SEQUENCE tour_advance_seq START WITH 1 INCREMENT BY 1 NOCACHE;

CREATE TABLE tour_advance (
  advance_id          NUMBER          NOT NULL,
  request_id          NUMBER          NOT NULL,
  line_no              NUMBER(4)      NOT NULL,
  category_code         VARCHAR2(40)  NOT NULL,
  applied_amount         NUMBER(12,2) DEFAULT 0 NOT NULL,
  forwarded_amount        NUMBER(12,2),
  recommended_amount       NUMBER(12,2),
  approved_amount           NUMBER(12,2),
  created_at                 TIMESTAMP  DEFAULT SYSTIMESTAMP NOT NULL,
  updated_at                  TIMESTAMP,
  CONSTRAINT pk_tour_advance PRIMARY KEY (advance_id),
  CONSTRAINT uq_tour_advance_line UNIQUE (request_id, line_no),
  CONSTRAINT fk_tour_advance_req FOREIGN KEY (request_id) REFERENCES tour_request (request_id) ON DELETE CASCADE,
  CONSTRAINT fk_tour_advance_cat FOREIGN KEY (category_code) REFERENCES advance_category (category_code),
  CONSTRAINT chk_tour_advance_amounts CHECK (       -- VAL-09: numeric, non-negative
    applied_amount >= 0 AND
    (forwarded_amount IS NULL OR forwarded_amount >= 0) AND
    (recommended_amount IS NULL OR recommended_amount >= 0) AND
    (approved_amount IS NULL OR approved_amount >= 0)
  )
);

CREATE INDEX idx_tour_advance_req ON tour_advance (request_id);

-- ---------------------------------------------------------------------------
-- TOUR_ATTACHMENT
-- SSoT §10: max 3 per request (enforced in service layer — see comment
-- below), jpeg/jpg/png/bmp/pdf only, server-validated by content not just
-- extension. Storage mechanism is TBD (SSoT §25); this schema supports
-- either DB BLOB (dev default, see ATTACHMENT_STORAGE_MODE) or an external
-- object-store URL.
-- ---------------------------------------------------------------------------
CREATE SEQUENCE tour_attachment_seq START WITH 1 INCREMENT BY 1 NOCACHE;

CREATE TABLE tour_attachment (
  attachment_id      NUMBER          NOT NULL,
  request_id          NUMBER         NOT NULL,
  attachment_name       VARCHAR2(200) NOT NULL,
  file_name              VARCHAR2(500) NOT NULL,
  file_extension           VARCHAR2(10) NOT NULL,
  mime_type                 VARCHAR2(100) NOT NULL,
  file_size_bytes             NUMBER   NOT NULL,
  content_blob                 BLOB,               -- used when ATTACHMENT_STORAGE_MODE = DB_BLOB
  storage_url                   VARCHAR2(2000),     -- used when an object store is adopted instead
  uploaded_by                    VARCHAR2(30) NOT NULL,
  uploaded_at                     TIMESTAMP DEFAULT SYSTIMESTAMP NOT NULL,
  CONSTRAINT pk_tour_attachment PRIMARY KEY (attachment_id),
  CONSTRAINT fk_tour_attachment_req FOREIGN KEY (request_id) REFERENCES tour_request (request_id) ON DELETE CASCADE,
  CONSTRAINT chk_tour_attachment_ext CHECK (LOWER(file_extension) IN ('jpeg', 'jpg', 'png', 'bmp', 'pdf')),
  CONSTRAINT chk_tour_attachment_size CHECK (file_size_bytes > 0)
);

CREATE INDEX idx_tour_attachment_req ON tour_attachment (request_id);

COMMENT ON TABLE tour_attachment IS
  'Max-3-per-request is enforced in the Node.js service layer inside the same '
  'transaction as the insert (an Oracle CHECK cannot count sibling rows); the '
  'service re-verifies the count under the row lock on tour_request to close '
  'the race between two concurrent uploads.';

-- ---------------------------------------------------------------------------
-- TOUR_WORKFLOW_HISTORY
-- SSoT §13: actor, timestamp, old/new status, action, remarks. Append-only.
-- ---------------------------------------------------------------------------
CREATE SEQUENCE tour_workflow_history_seq START WITH 1 INCREMENT BY 1 NOCACHE;

CREATE TABLE tour_workflow_history (
  history_id            NUMBER         NOT NULL,
  request_id             NUMBER        NOT NULL,
  actor_person_number      VARCHAR2(30) NOT NULL,
  actor_name                 VARCHAR2(240),
  role_code                    VARCHAR2(30) NOT NULL,
  action                         VARCHAR2(30) NOT NULL,
  old_status                      VARCHAR2(30),
  new_status                       VARCHAR2(30) NOT NULL,
  remarks                            VARCHAR2(2000),
  action_at                           TIMESTAMP DEFAULT SYSTIMESTAMP NOT NULL,
  CONSTRAINT pk_tour_workflow_history PRIMARY KEY (history_id),
  CONSTRAINT fk_tour_workflow_history_req FOREIGN KEY (request_id) REFERENCES tour_request (request_id) ON DELETE CASCADE,
  CONSTRAINT fk_tour_workflow_history_role FOREIGN KEY (role_code) REFERENCES application_role (role_code),
  CONSTRAINT chk_tour_workflow_action CHECK (action IN
    ('SUBMIT', 'FORWARD', 'RECOMMEND', 'APPROVE', 'REJECT', 'RETURN', 'CANCEL'))
);

CREATE INDEX idx_tour_workflow_history_req ON tour_workflow_history (request_id, action_at);

-- ---------------------------------------------------------------------------
-- AUDIT_LOG
-- SSoT §22: security/business audit beyond what workflow history captures
-- (logins, admin overrides, attachment access, TA-rule evaluations, etc.).
-- ---------------------------------------------------------------------------
CREATE SEQUENCE audit_log_seq START WITH 1 INCREMENT BY 1 NOCACHE;

CREATE TABLE audit_log (
  audit_id                NUMBER        NOT NULL,
  event_type                VARCHAR2(60) NOT NULL,
  entity_type                 VARCHAR2(60) NOT NULL,
  entity_id                     VARCHAR2(60),
  actor_person_number             VARCHAR2(30),
  actor_role                        VARCHAR2(30),
  event_at                            TIMESTAMP DEFAULT SYSTIMESTAMP NOT NULL,
  detail                                CLOB,
  ip_address                            VARCHAR2(60),
  correlation_id                          VARCHAR2(60),
  CONSTRAINT pk_audit_log PRIMARY KEY (audit_id)
);

CREATE INDEX idx_audit_log_entity ON audit_log (entity_type, entity_id);
CREATE INDEX idx_audit_log_event_at ON audit_log (event_at DESC);

COMMIT;
